void cx18_stream_free ( struct cx18_stream * s ) { struct cx18_mdl * mdl ; struct cx18_buffer * buf ; struct cx18 * cx = s -> cx ; CX18_DEBUG_INFO ( "Deallocating buffers for %s stream\n" , s -> name ) ; while ( ( mdl = cx18_dequeue ( s , & s -> q_idle ) ) ) { kfree ( mdl ) ; } while ( ! list_empty ( & s -> buf_pool ) ) { buf = list_first_entry ( & s -> buf_pool , cx18_buffer , list ) ; list_del_init ( & buf -> list ) ; dma_unmap_single ( & s -> cx -> pci_dev -> dev , buf -> dma_handle , s -> buf_size , s -> dma ) ; kfree ( buf -> buf ) ; kfree ( buf ) ; } } 